static Color navy=Color.FromArgb(24,47,77);static Brush B(Color c){return new SolidBrush(c);}static Font F(float s,bool bold=false){return new Font("Times New Roman",s,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);}
static void Cue(Graphics g,float x,float y,float dx,float dy){g.DrawLine(new Pen(Color.FromArgb(104,67,35),7),x+dx,y+dy,x,y);g.DrawLine(new Pen(Color.Silver,7),x,y,x-dx*.2f,y-dy*.2f);g.DrawLine(new Pen(Color.FromArgb(231,211,159),4),x-dx*.2f,y-dy*.2f,x-dx*.35f,y-dy*.35f);}
