string[] titles={"Prepare the canvas","Set the atmosphere","Ground & moonlight","Block in the plum","Add the autumn color","Nose & leather shoes","Shape the beard","Finish the base colors","Build depth","Define the lanterns","Catch the light","Dry & care for tools"};
string[] captions={"Start with your printed 8 x 10 canvas. Protect your table. Use thin coats; rinse and blot brushes between colors.","Mix blue, a speck of black and white for a smoky sky. Paint around every outline; leave the shapes white.","Mix brown, a speck of black and a little white for ground. Use white + a little yellow for the moon; paint bats black.","Mix red and blue with a touch of brown for plum. Paint the hat, brim and coat; keep the band and buckle white.","Mix yellow, a little red and a touch of brown for russet orange. Paint pumpkins and band, including buckle center. Leave faces and stems white.","For peach, mix white, a little yellow and a tiny touch of red. Paint the nose peach and shoes brown.","Paint beard and mustache white. Mix white with a speck of black and brown for warm gray; pull curved strokes toward the tips.","Mix green with a touch of brown for stems. Mix yellow with a touch of brown for the buckle rim. Let dry.","Mix red, blue, brown and a speck of black for hat shadows. Mix yellow, a little red and extra brown for pumpkin grooves. Blend softly.","Over dry paint, fill the pumpkins' printed eyes and mouths with black using a small brush. Keep the edges controlled.","Mix white with a little yellow for ivory. Add fine, curved highlights to the beard and small shine strokes to the shoes.","Let your canvas dry lying flat. Wash and reshape brushes, wipe the palette and close your paint pots."};
File.WriteAllLines(t+"captions.txt",captions);File.WriteAllLines(t+"headings.txt",titles);
var page=new Bitmap(2550,3300);page.SetResolution(300,300);using(var g=Graphics.FromImage(page)){g.Clear(Color.White);g.ScaleTransform(2550f/612,3300f/792);g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.TextRenderingHint=TextRenderingHint.AntiAliasGridFit;
// Retain the approved title, original logo, watercolor banner and footer as separate layout assets.
