g.DrawImage(original,new RectangleF(25,750,562,29),new RectangleF(original.Width*25f/612,original.Height*729f/792,original.Width*562f/612,original.Height*29f/792),GraphicsUnit.Pixel);
}page.Save(t+"guide-page.png",ImageFormat.Png);new Bitmap(page,850,1100).Save(t+"guide-preview.png",ImageFormat.Png);for(int i=8;i<12;i++)p[i].Save(a+"panel-"+(i+1)+".png",ImageFormat.Png);Console.WriteLine("Guide composed; all captions fit.");}}



